import {chromium} from 'playwright';

const URL = 'http://127.0.0.1:5181/';
const OUT = '/tmp/pwcheck';
const results = [];
const check = (name, ok, extra = '') => {
  results.push({name, ok});
  console.log(`${ok ? 'PASS' : 'FAIL'}  ${name}${extra ? '  — ' + extra : ''}`);
};

const browser = await chromium.launch();
const page = await browser.newPage({viewport: {width: 1280, height: 800}});
const consoleErrors = [];
page.on('console', msg => {
  if (msg.type() === 'error' || msg.type() === 'warning') consoleErrors.push(`${msg.type()}: ${msg.text()}`);
});
page.on('pageerror', err => consoleErrors.push(`pageerror: ${err.message}`));

await page.goto(URL, {waitUntil: 'networkidle'});

// Structure
check('heading "Вход" rendered', (await page.locator('h1', {hasText: 'Вход'}).count()) === 1);
const email = page.getByLabel('Email');
const password = page.getByLabel('Пароль');
check('email input reachable by label', (await email.count()) === 1);
check('password input reachable by label', (await password.count()) === 1);
check('email input type=email', (await email.getAttribute('type')) === 'email');
check('password input type=password', (await password.getAttribute('type')) === 'password');
check('password has no copy button', (await page.locator('button[aria-label*="опир"], button[aria-label*="Copy"], button[aria-label*="копир"]').count()) === 0);
const remember = page.getByRole('checkbox', {name: 'Запомнить меня'});
check('"Запомнить меня" checkbox present, unchecked', (await remember.count()) === 1 && !(await remember.isChecked()));
const submit = page.getByRole('button', {name: 'Войти'});
check('"Войти" submit button present', (await submit.count()) === 1 && (await submit.getAttribute('type')) === 'submit');

// Gravity styles applied (not unstyled)
const btnBg = await submit.evaluate(el => getComputedStyle(el).backgroundColor);
const bodyClass = await page.evaluate(() => document.body.className);
check('Gravity root class on body', bodyClass.includes('g-root'), bodyClass);
check('button has styled background', btnBg !== 'rgba(0, 0, 0, 0)' && btnBg !== '', btnBg);

await page.screenshot({path: `${OUT}/01-initial-desktop.png`, fullPage: true});

// Validation: empty submit
await submit.click();
const emailErr = page.getByText('Введите email');
const passErr = page.getByText('Введите пароль');
check('empty submit shows email required error', (await emailErr.count()) === 1);
check('empty submit shows password required error', (await passErr.count()) === 1);
await page.screenshot({path: `${OUT}/02-empty-submit-errors.png`, fullPage: true});

// Invalid email
await email.fill('not-an-email');
await email.blur();
await submit.click();
check('invalid email shows format error', (await page.getByText('Некорректный email').count()) === 1);
check('email field marked invalid', (await email.getAttribute('aria-invalid')) === 'true' || (await page.locator('.g-text-input_validation_invalid, [class*="invalid"]').count()) > 0);

// Fix input clears error
await email.fill('user@example.com');
check('editing email clears its error', (await page.getByText('Некорректный email').count()) === 0);

// Checkbox toggles
await remember.click();
check('remember-me checkbox toggles on click', await remember.isChecked());
await remember.click();
check('remember-me checkbox toggles off', !(await remember.isChecked()));
await remember.click();

// Valid submit: password still missing -> error; then fill
await submit.click();
check('password error still shown when only password missing', (await passErr.count()) === 1 && (await page.getByText('Введите email').count()) === 0);
await password.fill('secret123');
check('editing password clears its error', (await passErr.count()) === 0);

// Keyboard: Enter submits the form (no error left, so no crash)
await password.press('Enter');
await page.waitForTimeout(200);
check('form submit with valid values produces no validation errors', (await page.getByText('Введите').count()) === 0 && (await page.getByText('Некорректный').count()) === 0);

// Reveal button works
const revealBtn = page.locator('.g-password-input__reveal-button, button[aria-label*="оказать"], button[aria-label*="how"]').first();
const revealCount = await revealBtn.count();
check('password reveal button present', revealCount > 0);

await page.screenshot({path: `${OUT}/03-filled.png`, fullPage: true});

// Mobile viewport
await page.setViewportSize({width: 375, height: 700});
await page.waitForTimeout(200);
await page.screenshot({path: `${OUT}/04-mobile.png`, fullPage: true});
const overflow = await page.evaluate(() => document.documentElement.scrollWidth > window.innerWidth);
check('no horizontal overflow at 375px', !overflow);

// Dark theme check via prefers-color-scheme
const darkPage = await browser.newPage({viewport: {width: 1280, height: 800}, colorScheme: 'dark'});
await darkPage.goto(URL, {waitUntil: 'networkidle'});
const darkBodyClass = await darkPage.evaluate(() => document.body.className);
check('system dark theme resolves to g-root_theme_dark', darkBodyClass.includes('g-root_theme_dark'), darkBodyClass);
await darkPage.screenshot({path: `${OUT}/05-dark.png`, fullPage: true});
await darkPage.close();

console.log('\nConsole errors/warnings:', consoleErrors.length ? '\n  ' + consoleErrors.join('\n  ') : 'none');
const failed = results.filter(r => !r.ok).length;
console.log(`\n${results.length - failed}/${results.length} checks passed`);
await browser.close();
process.exit(failed ? 1 : 0);

