import {chromium} from 'playwright';
const b = await chromium.launch({args: ['--no-sandbox','--disable-gpu','--disable-dev-shm-usage']});
const p = await b.newPage({viewport: {width: 1280, height: 800}});
await p.route(/^https?:\/\/(?!127\.0\.0\.1)/, r => r.abort());
await p.goto('http://127.0.0.1:5181/', {waitUntil: 'networkidle'});
const info = await p.getByRole('button', {name: 'Войти'}).evaluate(el => {
  const cs = getComputedStyle(el);
  const inner = el.querySelector('*');
  return {
    buttonClass: el.className,
    buttonBg: cs.backgroundColor,
    buttonBgVar: cs.getPropertyValue('--g-button-background-color').trim(),
    bgImage: cs.backgroundImage,
    innerBg: inner ? getComputedStyle(inner).backgroundColor : null,
    innerTag: inner ? inner.tagName + '.' + inner.className : null,
    pixel: null,
  };
});
console.log(JSON.stringify(info, null, 2));
const box = await p.getByRole('button', {name: 'Войти'}).boundingBox();
const shot = await p.screenshot({clip: {x: box.x + 10, y: box.y + 4, width: 20, height: 10}});
console.log('button sample screenshot bytes:', shot.length);
await b.close();
EOF
timeout 120 node btn.mjs 2>&1 | tail -20

